var a=`1010-som-tam`;var s=`world-1010`;var t=`TH`;var n=`southeast-asia`;var r=4;var o=21;var g={en:`Som Tam`,ua:`Сом там`};var l={en:`Som Tam is a dish from Thailand prepared with papaya, carrot, garlic, bird's eye chili. This is a home-scale version with measured ingredients in the individual steps where they are used. Use firm unripe papaya; the ingredient catalog does not distinguish green papaya from ripe fruit.`,ua:`Сом там, страва кухні країни Таїланд, яку готують із таких продуктів: папая, морква, часник, перець чилі пташине око. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Використайте тверду недостиглу папаю; каталог не відрізняє зелену від стиглої.`};var d=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`papaya`,500,`g`],[`carrot`,130,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`garlic`,3,`clove`],[`bird-s-eye-chili`,3,`pcs`],[`fish-sauce`,35,`ml`],[`lime-juice`,50,`ml`],[`palm-sugar`,25,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`tomato`,200,`g`],[`green-beans`,120,`g`],[`tamarind-concentrate`,15,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`peanut`,70,`g`]]}];var m={slug:a,id:s,country:`TH`,region:n,servings:4,minutes:21,title:g,text:l,steps:d};export{t as country,m as default,s as id,o as minutes,n as region,r as servings,a as slug,d as steps,l as text,g as title};